	filters.Add(Builders<LogEntry>.Filter.Gte(x => x.LocalTime, str_CreateTime));
}
if (Tag.UI.日志查询.TXT_StartTime != null)
{
	DateTime end_CreateTime = Convert.ToDateTime(Tag.UI.日志查询.TXT_EndTime);
	filters.Add(Builders<LogEntry>.Filter.Lte(x => x.LocalTime, end_CreateTime));
}
if (Tag.UI.日志查询.Text_LogType != "无" && Tag.UI.日志查询.Text_LogType != null)
{
	filters.Add(Builders<LogEntry>.Filter.Eq(x => x.Category, Tag.UI.日志查询.Text_LogType));
}

if (Tag.UI.日志查询.Text_Field != "无" && !string.IsNullOrEmpty(Tag.UI.日志查询.Text_Field) && !string.IsNullOrEmpty(Tag.UI.日志查询.Text_QueryConditions))
{
	string name = Tag.UI.日志查询.Text_Field;
	if (name == "ProcessId" || name == "LineNo" || name == "TimeSpan" || name == "SequenceId")
	{
		if (name == "TimeSpan" && double.TryParse(Tag.UI.日志查询.Text_QueryConditions, out double douValue))
		{
			filters.Add(Builders<LogEntry>.Filter.Eq(name, Tag.UI.日志查询.Text_QueryConditions));
		}
		else if (int.TryParse(Tag.UI.日志查询.Text_QueryConditions, out int intValue))
		{
			filters.Add(Builders<LogEntry>.Filter.Eq(name, Tag.UI.日志查询.Text_QueryConditions));
		}
	}
	else if (name == "Title" || name == "Message" || name == "Tags" || name == "Category" || name == "LogicNo")
	{
		filters.Add(Builders<LogEntry>.Filter.Text(Tag.UI.日志查询.Text_QueryConditions) & Builders<LogEntry>.Filter.Regex(name, Tag.UI.日志查询.Text_QueryConditions));
	}
	else
	{
		filters.Add(Builders<LogEntry>.Filter.Regex(name, new BsonRegularExpression(Tag.UI.日志查询.Text_QueryConditions, "i")));
	}
}

switch (strCmd)
{
	case "First":
		Tag.UI.日志查询.Page_Number = 1;
